import { useState } from "react";

interface Message {
  _id?: string;
  username: string;
  message: string;
  type: "text" | "file";
  createdAt?: string;
}

interface Props {
  message: Message;
  currentUser: string;
  react: (id: string, emoji: string) => void;
}

export default function MessageBubble({
  message,
  currentUser,
  react
}: Props) {

  const isSent = message.username === currentUser;

  const [showReact, setShowReact] = useState(false);

  const time = message.createdAt
    ? new Date(message.createdAt).toLocaleTimeString([], {
        hour: "2-digit",
        minute: "2-digit"
      })
    : "";

  return (
    <div className={`flex ${isSent ? "justify-end" : ""}`}>

      <div
        onMouseEnter={() => setShowReact(true)}
        onMouseLeave={() => setShowReact(false)}
        className={`rounded-lg px-4 py-2 my-1 max-w-[70%] ${
          isSent ? "bg-blue-500 text-white" : "bg-gray-700 text-gray-200"
        }`}
      >

        {message.type === "file"
          ? <img src={message.message} className="max-h-40 rounded" />
          : message.message}

        <div className="text-[10px] opacity-70 text-right">
          {time}
        </div>

        {showReact && message._id && (
          <div className="flex gap-1 mt-1 text-xs">
            {["👍","❤️","😂"].map((e) => (
              <button
                key={e}
                onClick={() => react(message._id!, e)}
              >
                {e}
              </button>
            ))}
          </div>
        )}

      </div>

    </div>
  );
}